use vstd::prelude::*;

verus! {

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == m.len(),
        forall|i: int|
            0 <= i && i < m.len() ==> result[i] == m[m.len() - 1 - i],
{
    let n = m.len();
    let mut result: Vec<f32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            result.len() == i,
            i <= n,
            forall|j: int|
                0 <= j && j < i ==> result[j] == m[n - 1 - j],
    {
        result.push(m[n - 1 - i]);
        i += 1;
    }

    result
}

} // verus!